class Solution:
    def possibleBipartition(self, n: int, dislikes: list[list[int]]) -> bool:
        adj = [[] for _ in range(n + 1)]
        for a, b in dislikes:
            adj[a].append(b); adj[b].append(a)
        color = [0] * (n + 1)
        def backtrack(person):
            if person == n + 1:
                return True
            for c in (1, -1):
                if all(color[v] != c for v in adj[person]):
                    color[person] = c
                    if backtrack(person + 1):
                        return True
                    color[person] = 0
            return False
        return backtrack(1)

