class Solution:
    def possibleBipartition(self, n: int, dislikes: list[list[int]]) -> bool:
        from collections import deque
        adj = [[] for _ in range(n + 1)]
        for a, b in dislikes:
            adj[a].append(b); adj[b].append(a)
        color = [0] * (n + 1)
        for i in range(1, n + 1):
            if color[i] != 0:
                continue
            color[i] = 1; q = deque([i])
            while q:
                u = q.popleft()
                for v in adj[u]:
                    if color[v] == color[u]:
                        return False
                    if color[v] == 0:
                        color[v] = -color[u]; q.append(v)
        return True

